begin;
create temp table setup_fixture as select user_id u,partner_user_id p from partner_links where status='active' limit 1;
grant select on setup_fixture to authenticated;
create temp table setup_totals as select (select count(*) from transactions) transactions,(select count(*) from finance_documents where kind='close') closes;
-- Simulate a just-joined user without creating an identity or sending email.
delete from finance_setup_history where owner_id in(select u from setup_fixture);
delete from finance_setup_progress where owner_id in(select u from setup_fixture);
set local role authenticated;
do $$declare f record;r jsonb;blocked boolean;rev integer;begin
 select * into strict f from setup_fixture;perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claim.sub',f.u::text,true);
 r:=finance_get_setup();if (r->>'required')::boolean is distinct from true then raise exception 'New user did not get setup entry';end if;
 if finance_get_setup()<>r then raise exception 'Initialization is not idempotent';end if;
 insert into finance_module_preferences(owner_id,enabled_modules) values(f.u,array['everyday','income']) on conflict(owner_id) do update set enabled_modules=excluded.enabled_modules;
 r:=finance_update_setup('choose',null,null,(r->>'revision')::integer);
 rev:=(r->>'revision')::integer;
 r:=finance_update_setup('check','foundation.accounts',true,rev);
 if not(r->'checks' ? 'foundation.accounts') then raise exception 'Step confirmation lost';end if;
 blocked:=false;begin perform finance_update_setup('check','foundation.transactions',true,rev);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Stale browser overwrote progress';end if;
 blocked:=false;begin perform finance_update_setup('check','household.share.everything',true,(r->>'revision')::integer);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Unknown step accepted';end if;
 blocked:=false;begin perform finance_update_setup('finish',null,null,(r->>'revision')::integer);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Unreviewed undeferred modules completed';end if;
 r:=finance_update_setup('defer','foundation',null,(r->>'revision')::integer);r:=finance_update_setup('defer','everyday',null,(r->>'revision')::integer);r:=finance_update_setup('defer','income',null,(r->>'revision')::integer);
 r:=finance_update_setup('finish',null,null,(r->>'revision')::integer);if r->>'status'<>'finished' or not(r->'deferred' ? 'income') then raise exception 'Deferred module was not retained';end if;
 r:=finance_update_setup('resume','income',null,(r->>'revision')::integer);if r->'deferred' ? 'income' then raise exception 'Resume did not release module';end if;
 r:=finance_update_setup('check','income.paystub',true,(r->>'revision')::integer);
 update finance_module_preferences set enabled_modules=array['everyday'] where owner_id=f.u;
 if not(finance_get_setup()->'checks' ? 'income.paystub') then raise exception 'Hiding module lost its checks';end if;
 update finance_module_preferences set enabled_modules=array['everyday','income'] where owner_id=f.u;
 r:=finance_update_setup('pause',null,null,(r->>'revision')::integer);if r->>'status'<>'paused' then raise exception 'Pause failed';end if;
 r:=finance_update_setup('check','foundation.scope@0123456789abcdef',true,(r->>'revision')::integer);
 if r->'evidence_signatures'->>'foundation.scope'<>'0123456789abcdef' then raise exception 'Evidence signature lost';end if;
 blocked:=false;begin perform finance_update_setup('check','foundation.scope@not-a-signature',true,(r->>'revision')::integer);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Invalid signature accepted';end if;
 r:=finance_update_setup('check','foundation.scope',false,(r->>'revision')::integer);if r->'evidence_signatures' ? 'foundation.scope' then raise exception 'Old evidence not cleared';end if;
 blocked:=false;begin perform finance_update_setup('finish','["unknown.step"]',null,(r->>'revision')::integer);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Unknown recognition key accepted';end if;
 r:=finance_update_setup('finish','["foundation.accounts","foundation.transactions","foundation.scope","everyday.budget","everyday.bills","everyday.variance","income.paystub","income.deposits","income.mix"]',null,(r->>'revision')::integer);
 if r->>'status'<>'finished' or not(r->'recognized_keys' ? 'foundation.transactions') or r->'checks' ? 'foundation.transactions' then raise exception 'Recognized state was confused with a manual review';end if;
 r:=finance_update_setup('pause',null,null,(r->>'revision')::integer);
 if not exists(select 1 from finance_setup_history where owner_id=f.u and action='pause') then raise exception 'Progress audit missing';end if;
 blocked:=false;begin update finance_setup_progress set checks='{}' where owner_id=f.u;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Direct write bypassed revision checking';end if;
 perform set_config('request.jwt.claim.sub',f.p::text,true);
 if exists(select 1 from finance_setup_progress where owner_id=f.u) or exists(select 1 from finance_setup_history where owner_id=f.u) then raise exception 'Partner read private setup';end if;
 -- Partners can update only their own state, never the owner's state.
 r:=finance_get_setup();perform finance_update_setup('pause',null,null,(r->>'revision')::integer);
end;$$;
reset role;
do $$begin if (select count(*) from transactions)<>(select transactions from setup_totals) or (select count(*) from finance_documents where kind='close')<>(select closes from setup_totals) then raise exception 'Setup changed financial records';end if;end;$$;
set local role anon;
do $$declare blocked boolean:=false;begin begin perform finance_get_setup();exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Anonymous setup access';end if;end;$$;
reset role;rollback;
select 'PASS: new-user initialization, resumable checked/deferred state, private progress and audit, stale-write rejection, authenticated RPC only, no financial writes. Fixtures rolled back.' as result;
